//! Bidirectional dimensional conversions. No network or external accounts.
use crate::{*,serde_json::{json,Value}};
use super::calc::number;
#[derive(Clone,Copy)]struct Unit{key:&'static str,name:&'static str,factor:f64,offset:f64}
const fn u(key:&'static str,name:&'static str,factor:f64)->Unit{Unit{key,name,factor,offset:0.}}
fn units(category:&str)->Vec<Unit>{match category{
 "mass"=>vec![u("lb","Pounds (lb)",453.59237),u("oz","Ounces (oz)",28.349523125),u("g","Grams (g)",1.),u("kg","Kilograms (kg)",1000.),u("mg","Milligrams (mg)",0.001),u("st","Stones (st)",6350.29318),u("ton","US tons",907184.74),u("tonne","Metric tonnes",1000000.)],
 "temperature"=>vec![u("c","Celsius (°C)",1.),Unit{key:"f",name:"Fahrenheit (°F)",factor:5./9.,offset:-32.*5./9.},Unit{key:"k",name:"Kelvin (K)",factor:1.,offset:-273.15}],
 "volume"=>vec![u("ml","Milliliters (mL)",1.),u("l","Liters (L)",1000.),u("floz","US fluid ounces",29.5735295625),u("cup","US cups",236.5882365),u("tbsp","US tablespoons",14.78676478125),u("tsp","US teaspoons",4.92892159375),u("pint","US pints",473.176473),u("quart","US quarts",946.352946),u("gallon","US gallons",3785.411784),u("ukgallon","Imperial gallons (UK)",4546.09),u("ukfloz","Imperial fluid ounces (UK)",28.4130625)],
 "area"=>vec![u("ft2","Square feet",0.09290304),u("m2","Square meters",1.),u("in2","Square inches",0.00064516),u("acre","Acres",4046.8564224),u("ha","Hectares",10000.),u("km2","Square kilometers",1000000.),u("mi2","Square miles",2589988.110336)],
 "speed"=>vec![u("mph","Miles per hour",0.44704),u("kph","Kilometers per hour",1./3.6),u("ms","Meters per second",1.),u("kn","Knots",0.514444444444)],
 "time"=>vec![u("sec","Seconds",1.),u("min","Minutes",60.),u("hr","Hours",3600.),u("day","Days",86400.),u("week","Weeks",604800.)],
 "fraction"=>vec![u("decimal","Decimal",1.),u("fraction","Fraction",1.)],
 _=>vec![u("ft","Feet (ft)",0.3048),u("ftin","Feet + inches",0.3048),u("in","Inches (in)",0.0254),u("m","Meters (m)",1.),u("cm","Centimeters (cm)",0.01),u("mm","Millimeters (mm)",0.001),u("yd","Yards (yd)",0.9144),u("mi","Miles (mi)",1609.344),u("km","Kilometers (km)",1000.),u("um","Micrometers (µm)",0.000001)]}}
pub fn parse_number(raw:&str)->Result<f64,String>{let text=raw.trim().replace('−',"-");if text.len()>80||text.is_empty(){return Err("Enter a value".into())}let parts=text.split_whitespace().collect::<Vec<_>>();let value=if parts.len()==2{let whole=parts[0].parse::<f64>().map_err(|_|"Use a number or mixed fraction")?;let fraction=parse_number(parts[1])?;if parts[1].starts_with('-')||fraction<0.||fraction>=1.{return Err("Use a mixed fraction such as 2 3/4".into())}if parts[0].starts_with('-'){whole-fraction}else{whole+fraction}}else if parts.len()==1{if let Some((a,b))=text.split_once('/'){let a=a.parse::<f64>().map_err(|_|"Use a fraction such as 3/4")?;let b=b.parse::<f64>().map_err(|_|"Use a fraction such as 3/4")?;if b==0.{return Err("A fraction cannot have a zero denominator".into())}a/b}else{text.parse::<f64>().map_err(|_|"Enter a number or fraction")?}}else{return Err("Use a number or mixed fraction".into())};if !value.is_finite()||value.abs()>1e18{return Err("Value is too large".into())}Ok(value)}
fn feet(raw:&str)->Result<f64,String>{let s=raw.trim().replace("ft","'").replace("in","").replace('′',"'").replace(['"','″'],"");if let Some((a,b))=s.split_once('\''){let ft=parse_number(a)?;let inches=if b.trim().is_empty(){0.}else{parse_number(b)?};if !(0.0..12.).contains(&inches){return Err("Use inches from 0 to less than 12".into())}Ok(if a.trim().starts_with('-'){ft-inches/12.}else{ft+inches/12.})}else{parse_number(&s)}}
fn gcd(mut a:i64,mut b:i64)->i64{while b!=0{let t=a%b;a=b;b=t;}a.abs().max(1)}
fn fraction(n:f64,den:i64)->String{if n.abs()>1e9{return number(n)}let v=(n.abs()*den as f64).round()as i64;let whole=v/den;let num=v%den;let sign=if n<0.&&v!=0{"-"}else{""};if num==0{return format!("{sign}{whole}")}let g=gcd(num,den);if whole>0{format!("{sign}{whole} {}/{}",num/g,den/g)}else{format!("{sign}{}/{}",num/g,den/g)}}
fn format_value(n:f64,key:&str,den:i64)->String{match key{"fraction"=>fraction(n,den),"ftin"=>{let rounded=(n.abs()*12.*den as f64).round()/den as f64;let ft=(rounded/12.).floor();format!("{}{}′ {}″",if n<0.{"-"}else{""},number(ft),fraction(rounded-ft*12.,den))},_=>number(n)}}
fn calculate(s:&mut Value,reverse:bool){let list=units(s["category"].as_str().unwrap_or("length"));let Some(from)=list.iter().find(|u|u.key==s["from"]).copied()else{return};let Some(to)=list.iter().find(|u|u.key==s["to"]).copied()else{return};let(a,b,input,output)=if reverse{(to,from,"right","left")}else{(from,to,"left","right")};s["result"]=json!("");let source=s[input].as_str().unwrap_or("").to_owned();let raw=source.as_str();s[output]=json!("");if raw.trim().is_empty(){s[output]=json!("");s["error"]=json!("");return}match if a.key=="ftin"{feet(raw)}else{parse_number(raw)}{Ok(v)=>{let base=v*a.factor+a.offset;let n=(base-b.offset)/b.factor;if !n.is_finite()||n.abs()>1e18{s["error"]=json!("Result is too large");return}if s["category"]=="temperature"&&base< -273.15000001{s["error"]=json!("Temperature is below absolute zero");return}s["error"]=json!("");s[output]=json!(format_value(n,b.key,s["denominator"].as_str().and_then(|n|n.parse().ok()).unwrap_or(1000000)));s["value"]=json!(n);s["result"]=s[output].clone();},Err(err)=>{s["error"]=json!(err);s[output]=json!("");}}}
pub fn controller(input:Value)->Value{let mut s=input["state"].clone();if !s.is_object(){s=json!({"category":"length","from":"ft","to":"m","left":"1","right":"0.3048","error":"","denominator":"1000000","revision":0,"result":"0.3048"});}let e=&input["event"];let a=e["action"].as_str().unwrap_or("");let mut req=Value::Null;
 match a{"start"=>req=collections::get("convert_prefs_v1","settings","convert.loaded"),"convert.loaded" if e["reply"]["ok"]==true=>{s["revision"]=e["reply"]["value"]["revision"].clone();let p=&e["reply"]["value"]["data"];if p["category"].is_string(){for k in["category","from","to","denominator"]{s[k]=p[k].clone();}calculate(&mut s,false);}},"convert.saved" if e["reply"]["ok"]==true=>s["revision"]=e["reply"]["value"]["revision"].clone(),
 "convert.category"=>{s["category"]=e["value"].clone();let list=units(s["category"].as_str().unwrap_or("length"));s["from"]=json!(list[0].key);s["to"]=json!(if s["category"]=="length"{"m"}else if s["category"]=="mass"{"kg"}else{list[1].key});s["left"]=json!("1");calculate(&mut s,false);},
 "convert.from"|"convert.to"|"convert.denominator"=>{s[&a[8..]]=e["value"].clone();calculate(&mut s,false);},"convert.left"=>{s["left"]=e["value"].clone();calculate(&mut s,false);},"convert.right"=>{s["right"]=e["value"].clone();calculate(&mut s,true);},
 "convert.swap"=>{let from=s["from"].clone();s["from"]=s["to"].clone();s["to"]=from;let left=s["left"].clone();s["left"]=s["right"].clone();s["right"]=left;calculate(&mut s,false);},
 "convert.copy"=>req=effect("clipboard.write",json!({"text":s["result"]}),"convert.copied"),_=>{}}
 if matches!(a,"convert.category"|"convert.from"|"convert.to"|"convert.denominator"){req=collections::transact("convert_prefs_v1",s["revision"].as_u64().unwrap_or(0),1,None,vec![collections::put("settings",json!({"category":s["category"],"from":s["from"],"to":s["to"],"denominator":s["denominator"]}))],"convert.saved");}
 let list=units(s["category"].as_str().unwrap_or("length"));let options=list.iter().map(|u|(u.key,u.name)).collect::<Vec<_>>();let mut out=heading("convert.result",s["result"].as_str().unwrap_or("")).long_action("convert.copy","Copy conversion");out["font"]=json!(28);out["utility_display"]=json!(true);
 let mut n=vec![choices("chips","convert.category","Measurement",s["category"].as_str().unwrap_or("length"),&[("length","Length"),("mass","Weight"),("volume","Volume"),("temperature","Temperature"),("fraction","Fractions"),("area","Area"),("speed","Speed"),("time","Time")]),choices("select","convert.from","From",s["from"].as_str().unwrap_or("ft"),&options),field("convert.left",if s["from"]=="ftin"{"e.g. 5′ 7 1/2″"}else{"Value · e.g. 2.5 or 2 1/2"},s["left"].as_str().unwrap_or("")).limit(80),button("convert.swap","⇅  Swap units").subtle(),choices("select","convert.to","To",s["to"].as_str().unwrap_or("m"),&options),field("convert.right","Converted value",s["right"].as_str().unwrap_or("")).limit(80),label("convert.error",s["error"].as_str().unwrap_or("")),out];
 if s["category"]=="fraction"||s["from"]=="ftin"||s["to"]=="ftin"{n.push(choices("select","convert.denominator","Fraction precision",s["denominator"].as_str().unwrap_or("1000000"),&[("1000000","Decimal precision"),("16","Nearest 1/16"),("32","Nearest 1/32"),("64","Nearest 1/64")]));}
 Screen::new("Convert",s).body(n).scrollable().effect(req).finish()}
#[cfg(test)]mod tests{use super::*;#[test]fn fractions_and_feet_handle_signs_and_invalid_inputs(){assert_eq!(parse_number("-2 3/4").unwrap(),-2.75);assert_eq!(feet("5′ 7 1/2″").unwrap(),5.625);assert!(parse_number("3/0").is_err());assert!(parse_number("NaN").is_err());assert_eq!(fraction(2.75,1000000),"2 3/4");assert_eq!(format_value(5.625,"ftin",16),"5′ 7 1/2″");}
#[test]fn units_are_dimensionally_correct_and_round_trip(){for(cat,a,b,x,y)in[("length","in","cm",1.,2.54),("mass","lb","kg",1.,0.45359237),("volume","gallon","l",1.,3.785411784),("temperature","f","c",212.,100.),("temperature","c","f",-40.,-40.),("area","acre","m2",1.,4046.8564224)]{let mut s=json!({"category":cat,"from":a,"to":b,"left":number(x),"right":"","denominator":"1000000"});calculate(&mut s,false);assert!((s["value"].as_f64().unwrap()-y).abs()<1e-9,"{cat}");calculate(&mut s,true);assert!((s["value"].as_f64().unwrap()-x).abs()<1e-7,"{cat}");}}}

trait Subtle{fn subtle(self)->Self;}impl Subtle for Value{fn subtle(mut self)->Self{self["subtle"]=json!(true);self}}
